def build_file_map(files: List[Dict]) -> Dict[str, Dict]:
    file_map: Dict[str, Dict] = {}
    for f in files:
        file_map[f["path"]] = {
            "hash": sha256_text(f["content"]),
            "size": f["size"],
            "type": f["type"],
            "domains": f["domains"],
            "content": f["content"],
        }
    return file_map


def diff_files(cache: CacheManager, file_map: Dict[str, Dict]):
